// ═══════════════════════════════════════════════════════════════
//  核心算法 — 点数计算 & 拼点协议 & 伤害结算
// ═══════════════════════════════════════════════════════════════

import {
    type CardData,
    CardType,
    type ClashResult,
    type DamageCalculationContext,
    EffectType,
    type EffectInstance,
    type EntityStats,
    type PointCalculationContext,
} from '../types';
import {
    findEffect,
    applyEffect,
    getEffectStacks,
    hasEffect,
    reduceEffectStacks,
    removeEffect,
    isRuneProtectionActive,
} from './effects';
import { PAIN_CARD, PAIN_OATHS, type PainOath } from './cardRegistry';

// ═══════════════════════════════════════════════════════════════
//  A. 最终点数计算
// ═══════════════════════════════════════════════════════════════

/**
 * 计算最终点数
 * FinalPoint = (BaseDice * Multiplier + Addition) * BuffMod * RelicMod + BuffAdd + RelicAdd
 */
export function calculateFinalPoint(ctx: PointCalculationContext): number {
  const { baseDice, card, relicModifiers } = ctx;

  // Step 1-2: 卡牌基础计算
  let point = baseDice * card.calculation.multiplier + card.calculation.addition;

  // Step 3-4: 全局乘算修正
  point *= relicModifiers.globalMultiplier;

  // Step 5-6: 全局加算修正
  point += relicModifiers.globalAddition;

  const solitude = ctx.entityEffects
    .filter(effect => effect.type === EffectType.SOLITUDE)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (card.id !== 'pass' && solitude > 0) point += solitude;

  const mercy = (ctx.opponentEffects ?? [])
    .filter(effect => effect.type === EffectType.MERCY && effect.mercyCardType === card.type)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (card.id !== 'pass' && mercy > 0) point *= 0.5;

  return Math.max(0, Math.floor(point));
}

// ═══════════════════════════════════════════════════════════════
//  B. 拼点对撞协议
// ═══════════════════════════════════════════════════════════════

/**
 * 判断两张卡牌是否进入拼点流程
 * 1. 物理 vs 物理  2. 魔法 vs 魔法  3. 闪避 vs (物理|魔法)  4. 功能牌默认不拼点
 */
export function shouldClash(
  playerCard: CardData,
  enemyCard: CardData,
  forceClashFunction: boolean = false,
): boolean {
  const p = playerCard.type;
  const e = enemyCard.type;

  if (playerCard.ignoreClash || enemyCard.ignoreClash) return false;

  if (p === CardType.FUNCTION || e === CardType.FUNCTION) return forceClashFunction;
  if (p === e) return true;
  if (p === CardType.DODGE && (e === CardType.PHYSICAL || e === CardType.MAGIC)) return true;
  if (e === CardType.DODGE && (p === CardType.PHYSICAL || p === CardType.MAGIC)) return true;

  return false;
}

/**
 * 执行拼点结算
 * 常规：点大胜。闪避：闪避方点数 < 对方 = 闪避成功
 */
export function resolveClash(
  playerCard: CardData,
  enemyCard: CardData,
  playerPoint: number,
  enemyPoint: number,
): ClashResult {
  const isPlayerDodge = playerCard.type === CardType.DODGE;
  const isEnemyDodge = enemyCard.type === CardType.DODGE;

  // 玩家闪避
  if (isPlayerDodge && !isEnemyDodge) {
    if (playerPoint < enemyPoint) {
      return { outcome: 'dodge_success', playerFinalPoint: playerPoint, enemyFinalPoint: enemyPoint, message: `闪避成功！(${playerPoint} < ${enemyPoint})` };
    }
    return { outcome: 'enemy_win', playerFinalPoint: playerPoint, enemyFinalPoint: enemyPoint, message: `闪避失败！(${playerPoint} ≥ ${enemyPoint})` };
  }
  // 敌人闪避
  if (isEnemyDodge && !isPlayerDodge) {
    if (enemyPoint < playerPoint) {
      return { outcome: 'dodge_success', playerFinalPoint: playerPoint, enemyFinalPoint: enemyPoint, message: `敌方闪避成功！(${enemyPoint} < ${playerPoint})` };
    }
    return { outcome: 'player_win', playerFinalPoint: playerPoint, enemyFinalPoint: enemyPoint, message: `敌方闪避失败！(${enemyPoint} ≥ ${playerPoint})` };
  }
  // 常规
  if (playerPoint > enemyPoint) {
    return { outcome: 'player_win', playerFinalPoint: playerPoint, enemyFinalPoint: enemyPoint, message: `拼点胜利！(${playerPoint} > ${enemyPoint})` };
  } else if (enemyPoint > playerPoint) {
    return { outcome: 'enemy_win', playerFinalPoint: playerPoint, enemyFinalPoint: enemyPoint, message: `拼点失败！(${playerPoint} < ${enemyPoint})` };
  }
  return { outcome: 'draw', playerFinalPoint: playerPoint, enemyFinalPoint: enemyPoint, message: `势均力敌！(${playerPoint})` };
}

// ═══════════════════════════════════════════════════════════════
//  C. 伤害计算
// ═══════════════════════════════════════════════════════════════

/**
 * 原始伤害（未经防御修正）
 * relative: FinalPoint * scale + scaleAddition
 * fixed:    value
 * mixed:    baseValue + FinalPoint * scale + scaleAddition
 */
export function calculateRawDamage(finalPoint: number, card: CardData): number {
  const dl = card.damageLogic;
  switch (dl.mode) {
    case 'relative': return finalPoint * (dl.scale ?? 1) + (dl.scaleAddition ?? 0);
    case 'fixed':    return dl.value ?? 0;
    case 'mixed':    return (dl.baseValue ?? 0) + finalPoint * (dl.scale ?? 1) + (dl.scaleAddition ?? 0);
    default:         return 0;
  }
}

/**
 * 最终伤害（考虑攻防效果）
 * 链路：原始 → 寒冷减 → 增伤加 → 虚弱减 → 敏感增 → 坚固/屏障减伤 → 真实伤害跳过防御 → 结界 → 护甲
 */
export function calculateFinalDamage(ctx: DamageCalculationContext): { damage: number; isTrueDamage: boolean; logs: string[] } {
  const logs: string[] = [];
  let damage = calculateRawDamage(ctx.finalPoint, ctx.card);
  logs.push(`原始伤害: ${Math.floor(damage)}`);

  const isTrueDamage = ctx.isTrueDamage ?? false;

  // 寒冷减伤
  const cold = ctx.attackerEffects
    .filter(effect => effect.type === EffectType.COLD)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (cold > 0) { damage -= cold; logs.push(`[寒冷] -${cold}`); }

  // 增伤加算（仅直接攻击伤害链路）
  const damageBoost = ctx.attackerEffects
    .filter(effect => effect.type === EffectType.DAMAGE_BOOST)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (damageBoost > 0) { damage += damageBoost; logs.push(`[增伤] +${damageBoost}`); }

  const attackerCoDance = ctx.attackerEffects
    .filter(effect => effect.type === EffectType.CO_DANCE)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (attackerCoDance > 0) { damage += attackerCoDance; logs.push(`[共舞] 造成伤害 +${attackerCoDance}`); }

  // 虚弱减算（仅直接攻击伤害链路）
  const weaken = ctx.attackerEffects
    .filter(effect => effect.type === EffectType.WEAKEN)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (weaken > 0) { damage -= weaken; logs.push(`[虚弱] -${weaken}`); }

  // 非实体：仅影响当前卡牌造成的直接物理/魔法伤害
  const defenderHasNonEntity = ctx.defenderEffects.some((e) => e.type === EffectType.NON_ENTITY && e.stacks > 0);
  // 虚幻之躯：仅影响当前卡牌造成的直接物理伤害
  const defenderHasIllusoryBody = ctx.defenderEffects.some((e) => e.type === EffectType.ILLUSORY_BODY && e.stacks > 0);
  if (defenderHasNonEntity) {
    if (ctx.card.type === CardType.PHYSICAL) {
      damage *= 0.7;
      logs.push('[非实体] 物理伤害 x0.7');
    } else if (ctx.card.type === CardType.MAGIC) {
      damage *= 1.3;
      logs.push('[非实体] 魔法伤害 x1.3');
    }
  }
  if (defenderHasIllusoryBody && ctx.card.type === CardType.PHYSICAL) {
    damage *= 0.7;
    logs.push('[虚幻之躯] 物理伤害 x0.7');
  }

  const defenderHasIrisAmber = ctx.defenderEffects.some((e) => e.type === EffectType.IRIS_AMBER && e.stacks > 0);
  const defenderHasIrisScarlet = ctx.defenderEffects.some((e) => e.type === EffectType.IRIS_SCARLET && e.stacks > 0);
  if (defenderHasIrisAmber) {
    damage *= 0.5;
    logs.push('[虹膜：琥珀] 受到伤害 x0.5');
  }
  if (defenderHasIrisScarlet) {
    damage *= 1.25;
    logs.push('[虹膜：猩红] 受到伤害 x1.25');
  }

  const fantasyEmbrace = ctx.defenderEffects
    .filter(effect => effect.type === EffectType.FANTASY_EMBRACE)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (fantasyEmbrace > 0) {
    const reductionRate = Math.min(1, fantasyEmbrace * 0.12);
    damage *= Math.max(0, 1 - reductionRate);
    logs.push(`[虚妄之拥] 受到伤害 x${Math.max(0, 1 - reductionRate).toFixed(2)}`);
  }

  const defenderCoDance = ctx.defenderEffects
    .filter(effect => effect.type === EffectType.CO_DANCE)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (defenderCoDance > 0) { damage += defenderCoDance; logs.push(`[共舞] 受到伤害 +${defenderCoDance}`); }

  if (isTrueDamage) {
    logs.push(`真实伤害，无视防御。`);
    return { damage: Math.max(0, Math.floor(damage)), isTrueDamage: true, logs };
  }

  // 敏感仅影响非真实伤害
  const vuln = ctx.defenderEffects
    .filter(effect => effect.type === EffectType.VULNERABLE)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (vuln > 0) { damage += vuln; logs.push(`[敏感] +${vuln}`); }

  // 坚固固定减伤
  const sturdy = ctx.defenderEffects
    .filter(effect => effect.type === EffectType.STURDY)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (sturdy > 0) { damage -= sturdy; logs.push(`[坚固] -${sturdy}`); }

  // 结界的“抵挡并消耗”在 applyDamageToEntity 里处理，这里只记录提示
  if (ctx.defenderEffects.some(e => e.type === EffectType.BARRIER && e.stacks > 0)) {
    logs.push(`[结界] 对方有结界，本次非真实伤害将被抵挡。`);
  }

  // 护甲的实际消耗由 applyDamageToEntity 处理，这里只做预览提示
  const armor = ctx.defenderEffects
    .filter(effect => effect.type === EffectType.ARMOR)
    .reduce((total, effect) => total + Math.max(0, effect.stacks), 0);
  if (armor > 0) { logs.push(`[护甲] 对方有 ${armor} 层护甲`); }

  return { damage: Math.max(0, Math.floor(damage)), isTrueDamage: false, logs };
}

/**
 * 应用伤害到实体（含效果层数消耗），返回实际伤害
 */
export function triggerSwarmReviveIfNeeded(
  target: EntityStats,
  options?: { disableRevive?: boolean },
): { revived: boolean; logs: string[] } {
  const logs: string[] = [];
  if (target.hp > 0) return { revived: false, logs };
  if (target.maxHp <= 0) return { revived: false, logs };
  const mirrorRegeneration = findEffect(target, EffectType.REGENERATION);
  if (!options?.disableRevive && mirrorRegeneration && mirrorRegeneration.stacks > 0) {
    target.hp = 1;
    mirrorRegeneration.runtimeCounter = Math.max(3, Math.floor(mirrorRegeneration.runtimeCounter ?? 0));
    mirrorRegeneration.lockDecayThisTurn = true;
    applyEffect(target, EffectType.STUN, 1, {
      source: 'effect:mirror_regeneration',
      lockDecayThisTurn: true,
    });
    logs.push('[再生] 触发：生命锁定为1，进入3回合眩晕与伤害转化。');
    return { revived: true, logs };
  }
  if (options?.disableRevive) {
    const hasAnyRevive =
      getEffectStacks(target, EffectType.SWARM) > 0
      || getEffectStacks(target, EffectType.MIRROR_SWARM) > 0
      || getEffectStacks(target, EffectType.BLOOD_COCOON) > 0
      || getEffectStacks(target, EffectType.INDOMITABLE) > 0
      || getEffectStacks(target, EffectType.REGENERATION) > 0;
    void hasAnyRevive;
    return { revived: false, logs };
  }

  const swarmStacks = getEffectStacks(target, EffectType.SWARM);
  if (swarmStacks > 0) {
    reduceEffectStacks(target, EffectType.SWARM, 1);
    const swarmHealReduction = Math.max(0, Math.floor(target.swarmHealReduction ?? 0));
    const revivedHp = Math.max(0, target.maxHp - swarmHealReduction);
    if (revivedHp <= 0) {
      target.hp = 0;
      logs.push(`[群集] 触发复苏，但受群攻影响无法恢复生命值。`);
      return { revived: false, logs };
    }
    target.hp = revivedHp;
    logs.push(`[群集] 触发复苏，消耗1层并恢复至${revivedHp}生命。`);
    return { revived: true, logs };
  }

  const mirrorSwarmStacks = getEffectStacks(target, EffectType.MIRROR_SWARM);
  if (mirrorSwarmStacks > 0) {
    reduceEffectStacks(target, EffectType.MIRROR_SWARM, 1);
    const swarmHealReduction = Math.max(0, Math.floor(target.swarmHealReduction ?? 0));
    const revivedHp = Math.max(1, target.maxHp - swarmHealReduction);
    target.hp = revivedHp;
    logs.push(`[镜·群集] 触发复苏，消耗1层并恢复至${revivedHp}生命。`);
    return { revived: true, logs };
  }

  const bloodCocoonStacks = getEffectStacks(target, EffectType.BLOOD_COCOON);
  if (bloodCocoonStacks > 0) {
    reduceEffectStacks(target, EffectType.BLOOD_COCOON, 1);
    const recoverHp = Math.max(1, Math.floor(target.maxHp * 0.5));
    target.hp = recoverHp;
    logs.push(`[血茧] 触发，消耗1层并恢复至${recoverHp}点生命。`);
    return { revived: true, logs };
  }

  const indomitableStacks = getEffectStacks(target, EffectType.INDOMITABLE);
  if (indomitableStacks > 0) {
    reduceEffectStacks(target, EffectType.INDOMITABLE, 1);
    target.hp = 1;
    logs.push(`[不屈] 触发，消耗1层并恢复至1点生命。`);
    return { revived: true, logs };
  }

  return { revived: false, logs };
}

/**
 * 攻击段结算后处理攻击者寒冷：每次攻击段后层数减半（向下取整）
 * 即使该段实际伤害为 0 也会消耗寒冷。
 */
export function consumeColdAfterDealingDamage(attacker: EntityStats, actualDamage: number): string[] {
  const logs: string[] = [];
  void actualDamage;

  const cold = findEffect(attacker, EffectType.COLD);
  if (!cold || cold.stacks <= 0) return logs;

  const before = cold.stacks;
  cold.stacks = Math.floor(cold.stacks / 2);
  if (cold.stacks <= 0) {
    removeEffect(attacker, EffectType.COLD);
    logs.push(`[寒冷] ${before} -> 0（已消失）`);
  } else {
    logs.push(`[寒冷] ${before} -> ${cold.stacks}`);
  }
  return logs;
}

/**
 * 应用伤害到实体（含结界/护甲/群集/不屈），返回实际伤害
 */
export function applyDamageToEntity(
  target: EntityStats,
  damage: number,
  isTrueDamage: boolean,
  options?: { disableRevive?: boolean; swarmAttack?: boolean },
): { actualDamage: number; logs: string[]; limitOverflow: number; damageBeforeLimit?: number } {
  const logs: string[] = [];
  let limitOverflow = 0;
  let damageBeforeLimit: number | undefined;
  if (!isTrueDamage && damage > 0 && isRuneProtectionActive(target)) {
    logs.push(`[符文防护] 免疫${Math.floor(damage)}点非真实伤害。`);
    return { actualDamage: 0, logs, limitOverflow: 0 };
  }
  if (!options?.swarmAttack && getEffectStacks(target, EffectType.CLUSTER_CREATURE) > 0 && damage > 0) {
    const beforeClusterReduction = Math.max(0, Math.floor(damage));
    damage = Math.floor(beforeClusterReduction * 0.5);
    logs.push(`[集群生物] 非群攻伤害减半：${beforeClusterReduction} -> ${damage}。`);
  }
  const mirrorRegeneration = findEffect(target, EffectType.REGENERATION);
  if (mirrorRegeneration && mirrorRegeneration.stacks > 0 && Math.floor(mirrorRegeneration.runtimeCounter ?? 0) > 0) {
    const convertedDamage = Math.max(0, Math.floor(damage));
    if (convertedDamage <= 0) return { actualDamage: 0, logs, limitOverflow: 0 };
    const maxHpBefore = target.maxHp;
    applyEffect(target, EffectType.MAX_HP_REDUCTION, convertedDamage, { source: 'effect:mirror_regeneration' });
    const actualMaxHpLoss = Math.max(0, maxHpBefore - target.maxHp);
    logs.push(`[再生] 免疫 ${convertedDamage} 点伤害，并转化为 ${actualMaxHpLoss} 点生命上限削减。`);
    if (target.maxHp <= 0) {
      target.hp = 0;
      logs.push('[再生] 生命上限归零，镜像崩解。');
    } else {
      target.hp = Math.max(1, Math.min(target.hp, target.maxHp));
    }
    return { actualDamage: 0, logs, limitOverflow: 0 };
  }
  if (!isTrueDamage) {
    const damageLimit = getEffectStacks(target, EffectType.DAMAGE_LIMIT);
    if (damageLimit > 0 && damage > damageLimit) {
      damageBeforeLimit = damage;
      limitOverflow = Math.max(0, Math.floor(damage - damageLimit));
      logs.push(`[限伤] ${damage} -> ${damageLimit}`);
      damage = damageLimit;
    }
    if (hasEffect(target, EffectType.BARRIER) && damage > 0) {
      reduceEffectStacks(target, EffectType.BARRIER);
      logs.push(`[结界] 层数-1。`);
      return { actualDamage: 0, logs, limitOverflow, damageBeforeLimit };
    }
    const ae = findEffect(target, EffectType.ARMOR);
    if (ae && ae.stacks > 0 && damage > 0) {
      const c = Math.min(ae.stacks, damage);
      ae.stacks -= c; damage -= c;
      if (ae.stacks <= 0) removeEffect(target, EffectType.ARMOR);
      logs.push(`[护甲] 消耗${c}，剩余伤害${damage}。`);
    }
  }
  const actual = Math.min(damage, target.hp);
  target.hp -= actual;
  logs.push(`受到${actual}点伤害(HP: ${target.hp}/${target.maxHp})。`);
  if (options?.swarmAttack && actual > 0) {
    target.swarmHealReduction = Math.max(0, Math.floor(target.swarmHealReduction ?? 0) + actual);
    logs.push(`[群攻] 本场群集回复生命值上限减少 ${actual}，当前累计减少 ${target.swarmHealReduction}。`);
  }
  const reviveResult = triggerSwarmReviveIfNeeded(target, {
    disableRevive: options?.disableRevive,
  });
  logs.push(...reviveResult.logs);
  return { actualDamage: actual, logs, limitOverflow, damageBeforeLimit };
}

// ═══════════════════════════════════════════════════════════════
//  D. 拼点附带效果 & 攻击后效果
// ═══════════════════════════════════════════════════════════════

/** 拼点时：流血(真实伤害), 燃烧(胜方清除) */
export function processClashEffects(winner: EntityStats, loser: EntityStats): string[] {
  const logs: string[] = [];
  const bleed = getEffectStacks(loser, EffectType.BLEED);
  if (bleed > 0) { loser.hp -= bleed; logs.push(`[流血] 败方受${bleed}真实伤害。`); }
  if (hasEffect(winner, EffectType.BURN)) { removeEffect(winner, EffectType.BURN); logs.push(`[燃烧] 胜方燃烧消失。`); }
  return logs;
}

/** 攻击后：蓄力清除, 寒冷减半 */
export function processPostAttackEffects(_attacker: EntityStats): string[] {
  const logs: string[] = [];
  // 蓄力改为“下次掷骰时消耗”，寒冷改为“每次实际造成伤害后消耗”，这里不再处理。
  return logs;
}

// ═══════════════════════════════════════════════════════════════
//  E. 骰子工具
// ═══════════════════════════════════════════════════════════════

export function rollDice(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// 佩恩场景：累计损血、双向伤害收益与转阶段。
type PainSide = 'player' | 'enemy';

export interface PainSceneState {
  effects: EffectInstance[];
  initialCombinedMaxHp: number;
  totalHpLost: number;
  nextRollBonus: Record<PainSide, number>;
  phase: 1 | 2;
  phaseTwoActive: boolean;
  armorBlockedTurn: number;
}

export function createPainScene(player: EntityStats, enemy: EntityStats): PainSceneState {
  return {
    effects: [
      { type: EffectType.SELF_CHOSEN_PAIN, stacks: 1, polarity: 'scene' },
      { type: EffectType.CORRIDOR_MEMORY, stacks: 0, polarity: 'scene' },
    ],
    initialCombinedMaxHp: Math.max(1, player.maxHp + enemy.maxHp), totalHpLost: 0,
    nextRollBonus: { player: 0, enemy: 0 }, phase: 1, phaseTwoActive: false, armorBlockedTurn: -1,
  };
}

export function getPainOath(state: PainSceneState, type: PainOath): EffectInstance | undefined {
  return state.effects.find(effect => effect.type === type);
}

export function availablePainOaths(state: PainSceneState, player: EntityStats): PainOath[] {
  return PAIN_OATHS.filter(type => !getPainOath(state, type)
    && (type !== EffectType.PAIN_OATH_OINTMENT || player.hp <= player.maxHp * 0.75)
    && (type !== EffectType.PAIN_OATH_SHARE || getEffectStacks(player, EffectType.BLEED) > 0));
}

export function choosePainOath(state: PainSceneState, type: PainOath, turn: number, player: EntityStats): boolean {
  if (!availablePainOaths(state, player).includes(type)) return false;
  state.effects.push({ type, stacks: 1, polarity: 'scene', runtimeCounter: turn });
  return true;
}

export function addPainMemory(enemy: EntityStats, amount: number): void {
  const effect = findEffect(enemy, EffectType.PAIN_MEMORY);
  if (effect) effect.stacks = Math.max(0, Math.min(9, effect.stacks + amount));
  else if (amount > 0) applyEffect(enemy, EffectType.PAIN_MEMORY, Math.min(9, amount));
}

export function recordPainHpLoss(state: PainSceneState, side: PainSide, amount: number, trueDamage: boolean,
  player: EntityStats, enemy: EntityStats, selfHarm = false): void {
  if (amount <= 0) return;
  if (side === 'enemy') addPainMemory(enemy, trueDamage ? 2 : 1);
  if (trueDamage || selfHarm) state.nextRollBonus[side] += 1;
  state.totalHpLost += amount;
  const memory = state.effects.find(effect => effect.type === EffectType.CORRIDOR_MEMORY)!;
  memory.stacks = Math.min(60, Math.floor(state.totalHpLost * 100 / state.initialCombinedMaxHp));
  const tier = Math.floor(memory.stacks / 20);
  // Keep scene bonuses separate from other damage boosts so tier changes do not overwrite them.
  for (const [entity, multiplier] of [[enemy, 2], [player, 4]] as const) {
    let boost = entity.effects.find(effect => effect.type === EffectType.DAMAGE_BOOST && effect.source === 'scene:corridor');
    if (!boost && tier > 0) {
      boost = { type: EffectType.DAMAGE_BOOST, stacks: 0, polarity: 'buff', source: 'scene:corridor' };
      entity.effects.push(boost);
    }
    if (boost) boost.stacks = tier * multiplier;
  }
}

export function painIncomingDamage(state: PainSceneState, side: PainSide, amount: number, trueDamage: boolean): number {
  return side === 'player' && trueDamage && getPainOath(state, EffectType.PAIN_OATH_OINTMENT)
    ? Math.ceil(amount * 1.25) : amount;
}

export function consumePainRollBonus(state: PainSceneState, side: PainSide, rolled: number): number {
  const bonus = state.nextRollBonus[side];
  state.nextRollBonus[side] = 0;
  return rolled + bonus;
}

export function painOutgoingDamage(state: PainSceneState, source: PainSide, amount: number, turn: number): number {
  if (amount <= 0) return amount;
  const whip = getPainOath(state, EffectType.PAIN_OATH_WHIP);
  return source === 'player' && whip && turn === (whip.runtimeCounter ?? 0) + 1 ? amount * 2 : amount;
}

export function painHealingAmount(state: PainSceneState, side: PainSide, amount: number): number {
  return side === 'player' && getPainOath(state, EffectType.PAIN_OATH_SHARE) ? Math.floor(amount / 2) : amount;
}

export function painPointBonus(card: CardData, enemy: EntityStats): number {
  if (card.id !== PAIN_CARD.RETURN && card.id !== PAIN_CARD.REMEMBER) return 0;
  return Math.min(card.id === PAIN_CARD.RETURN ? 4 : 9, getEffectStacks(enemy, EffectType.PAIN_MEMORY)) * 2;
}

export function changePainThorns(enemy: EntityStats, amount: number): void {
  const stacks = Math.max(0, Math.min(10, getEffectStacks(enemy, EffectType.THORNS) + amount));
  removeEffect(enemy, EffectType.THORNS);
  if (stacks > 0) applyEffect(enemy, EffectType.THORNS, stacks);
}

export function painThornsOnPlayerCard(state: PainSceneState, enemy: EntityStats, card: CardData): void {
  if (!state.phaseTwoActive) return;
  if (card.type === CardType.PHYSICAL || card.type === CardType.MAGIC) changePainThorns(enemy, -2);
  else if (card.type === CardType.FUNCTION || card.type === CardType.DODGE || card.id === 'pass') changePainThorns(enemy, 2);
}

export function updatePainPhase(state: PainSceneState, enemy: EntityStats): boolean {
  if (state.phase === 2) return false;
  const transition = getEffectStacks(enemy, EffectType.PHASE_TRANSITION);
  if (transition > 0 && enemy.hp > transition) return false;
  state.phase = 2;
  removeEffect(enemy, EffectType.PHASE_TRANSITION);
  return true;
}
